<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForge\POD\ArtworkPixelQa;
use DigiForge\POD\RasterArtworkCodec;
use DigiForge\POD\RasterPdfAdapter;
foreach(['ArtworkGeometryQa','ArtworkPixelQa','RasterArtworkCodec','RasterPdfAdapter']as $class){$file=__DIR__.'/../../includes/POD/'.$class.'.php';if(is_file($file))require_once $file;}
final class ArtworkPixelQaTest extends TestCase {
 private function area(string $position='front'):array {return ['position'=>$position,'width_px'=>4,'height_px'=>4,'dpi'=>300,'qa_geometry'=>['safe_zone'=>['x'=>1,'y'=>1,'width'=>2,'height'=>2],'seam_exclusions'=>[],'min_image_dpi'=>300,'bleed'=>['trim_box'=>['x'=>1,'y'=>1,'width'=>2,'height'=>2],'margins_px'=>['left'=>1,'right'=>1,'top'=>1,'bottom'=>1]]]];}
 private function image():array{return RasterArtworkCodec::decode(RasterArtworkCodec::encode(4,4,str_repeat("\xff\x00\x00\xff",16)));}
 public function testActualPixelsCoverExplicitBleedAndNeverCertifySupplier():void {self::assertTrue(class_exists(ArtworkPixelQa::class));$qa=ArtworkPixelQa::verify([$this->area()],['front'=>$this->image()]);self::assertSame('VERIFIED_LOCAL_BLEED_PIXELS',$qa['panels']['front']['bleed_pixels']);self::assertFalse($qa['supplier_certified']);}
 public function testTransparentBleedPixelIsDenied():void {self::assertTrue(class_exists(ArtworkPixelQa::class));$image=$this->image();$image['rgba'][3]="\0";$this->expectException(InvalidArgumentException::class);ArtworkPixelQa::verify([$this->area()],['front'=>$image]);}
 public function testMissingSupplierContractsRemainExplicit():void {self::assertTrue(class_exists(ArtworkPixelQa::class));$qa=ArtworkPixelQa::verify([['position'=>'front','width_px'=>4,'height_px'=>4]],[]);self::assertSame('MISSING_BLEED_GEOMETRY',$qa['panels']['front']['bleed_pixels']);self::assertSame('MISSING_PANEL_CONTINUITY_CONTRACT',$qa['panel_continuity']);}
 public function testExactReviewedPanelEdgesAreComparedFromPixels():void {self::assertTrue(class_exists(ArtworkPixelQa::class));$front=$this->area();$back=$this->area('back');$front['panel_edge_matches']=[['edge'=>'right','other_panel'=>'back','other_edge'=>'left','reverse'=>false]];$images=['front'=>$this->image(),'back'=>$this->image()];self::assertSame('VERIFIED_LOCAL_EDGE_CONTINUITY',ArtworkPixelQa::verify([$front,$back],$images)['panel_continuity']);$images['back']['rgba'][0]="\0";$this->expectException(InvalidArgumentException::class);ArtworkPixelQa::verify([$front,$back],$images);}
 public function testPdfPixelInspectionPreservesExactStoredImage():void {$rgb=str_repeat("\xff\x00\x00",16);$pdf=RasterPdfAdapter::encode(4,4,$rgb,300);self::assertTrue(method_exists(RasterPdfAdapter::class,'pixels'));$image=RasterPdfAdapter::pixels($pdf);self::assertSame(str_repeat("\xff\x00\x00\xff",16),$image['rgba']);self::assertSame(300,$image['dpi']);}
 public function testMissingReferencedPanelCannotBeTreatedAsContinuityPass():void {self::assertTrue(class_exists(ArtworkPixelQa::class));$front=$this->area();$front['panel_edge_matches']=[['edge'=>'right','other_panel'=>'missing','other_edge'=>'left','reverse'=>false]];$this->expectException(InvalidArgumentException::class);ArtworkPixelQa::verify([$front],['front'=>$this->image()]);}
 public function testReviewedReverseOrientationUsesWholePixels():void {$front=$this->area();$back=$this->area('back');$front['panel_edge_matches']=[['edge'=>'right','other_panel'=>'back','other_edge'=>'left','reverse'=>true]];$a=$this->image();$b=$this->image();for($y=0;$y<4;$y++){$color=chr($y*40)."\x10\x20\xff";$a['rgba']=substr_replace($a['rgba'],$color,($y*4+3)*4,4);$b['rgba']=substr_replace($b['rgba'],$color,((3-$y)*4)*4,4);}self::assertSame('VERIFIED_LOCAL_EDGE_CONTINUITY',ArtworkPixelQa::verify([$front,$back],['front'=>$a,'back'=>$b])['panel_continuity']);$front['panel_edge_matches'][0]['reverse']=false;$this->expectException(InvalidArgumentException::class);ArtworkPixelQa::verify([$front,$back],['front'=>$a,'back'=>$b]);}
}
